def clean(df):
    df = df.copy()
    # drop exact duplicate rows
    df = df.drop_duplicates()
    # strip whitespace for text columns
    for col in ['species','island','sex']:
        if col in df.columns:
            df[col] = df[col].apply(lambda x: x.strip() if isinstance(x, str) else x)
    # fix label variants in species: ' Adelie' -> 'Adelie', 'Chinstarp' -> 'Chinstrap'
    species_map = {'Adelie': 'Adelie', 'Chinstrap': 'Chinstrap', 'Gentoo': 'Gentoo', 'Chinstarp': 'Chinstrap'}
    if 'species' in df.columns:
        df['species'] = df['species'].replace(species_map)
        # fallback: title case strip
        df['species'] = df['species'].apply(lambda x: species_map.get(x, x) if isinstance(x, str) else x)
    # convert numeric columns that may be stored as text
    for col in ['bill_length_mm','bill_depth_mm','flipper_length_mm','body_mass_g','year']:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')
    # fix negative flipper_length_mm (data entry sign error) -> abs
    if 'flipper_length_mm' in df.columns:
        df['flipper_length_mm'] = df['flipper_length_mm'].abs()
        df.loc[(df['flipper_length_mm'] < 170) | (df['flipper_length_mm'] > 235), 'flipper_length_mm'] = pd.NA
    # fix out_of_range body_mass_g (e.g. 3500000 instead of 3500) -> try /1000
    if 'body_mass_g' in df.columns:
        mask = df['body_mass_g'] > 6500
        df.loc[mask, 'body_mass_g'] = df.loc[mask, 'body_mass_g'] / 1000
        df.loc[(df['body_mass_g'] < 2500) | (df['body_mass_g'] > 6500), 'body_mass_g'] = pd.NA
    if 'bill_length_mm' in df.columns:
        df.loc[(df['bill_length_mm'] < 30) | (df['bill_length_mm'] > 60), 'bill_length_mm'] = pd.NA
    return df

def answer(df):
    # average bill_length_mm by island for Adelie penguins
    d = df[df['species'] == 'Adelie'].copy()
    d = d.dropna(subset=['island','bill_length_mm'])
    # drop missing group keys (island already filtered) and ensure island is allowed
    d = d[d['island'].isin(['Biscoe','Dream','Torgersen'])]
    grp = d.groupby('island')['bill_length_mm'].mean()
    return {str(k): float(v) for k, v in grp.items()}
